<?php
/** Safe, explicit demo installer and admin screen. */
if (!defined('ABSPATH')) { exit; }
require_once get_template_directory().'/inc/demo-data.php';
const STILLFORM_DEMO_OWNER='stillform-demo-v1';
function stillform_demo_find_owned($type,$key){$ids=get_posts(['post_type'=>$type,'post_status'=>'any','fields'=>'ids','posts_per_page'=>1,'meta_query'=>[['key'=>'_stillform_demo_owner','value'=>STILLFORM_DEMO_OWNER],['key'=>'_stillform_demo_key','value'=>$key]]]);return $ids?(int)$ids[0]:0;}
function stillform_demo_mark($id,$key){update_post_meta($id,'_stillform_demo_owner',STILLFORM_DEMO_OWNER);update_post_meta($id,'_stillform_demo_key',$key);}
function stillform_demo_upsert($type,$slug,$title,$content,$excerpt='',$template=''){$key=$type.':'.$slug;$id=stillform_demo_find_owned($type,$key);$conflict=get_page_by_path($slug,OBJECT,[$type]);if(!$id&&$conflict)return['id'=>(int)$conflict->ID,'owned'=>false,'status'=>'preserved'];$data=['post_type'=>$type,'post_name'=>$slug,'post_title'=>$title,'post_content'=>$content,'post_excerpt'=>$excerpt,'post_status'=>'publish'];if($id){$data['ID']=$id;$id=wp_update_post($data,true);}else{$id=wp_insert_post($data,true);}if(is_wp_error($id))return$id;stillform_demo_mark($id,$key);if($template)update_post_meta($id,'_wp_page_template',$template);return['id'=>(int)$id,'owned'=>true,'status'=>isset($data['ID'])?'updated':'created'];}
function stillform_demo_media($file,$data){$key='attachment:'.$file;$id=stillform_demo_find_owned('attachment',$key);if($id)return$id;$path=get_template_directory().'/assets/images/architecture/'.$file;if(!is_readable($path))return new WP_Error('stillform_missing_image',sprintf(__('Missing bundled image: %s','stillform'),$file));require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/image.php';$upload=wp_upload_bits($file,null,file_get_contents($path));if(!empty($upload['error']))return new WP_Error('stillform_upload_error',$upload['error']);$type=wp_check_filetype($file);$id=wp_insert_attachment(['post_mime_type'=>$type['type'],'post_title'=>$data[0],'post_status'=>'inherit'],$upload['file']);if(is_wp_error($id))return$id;wp_update_attachment_metadata($id,wp_generate_attachment_metadata($id,$upload['file']));update_post_meta($id,'_wp_attachment_image_alt',$data[1]);stillform_demo_mark($id,$key);update_post_meta($id,'_stillform_source_url',esc_url_raw($data[2]));update_post_meta($id,'_stillform_license','Unsplash License — https://unsplash.com/license');return(int)$id;}
function stillform_install_demo_content(){if(!current_user_can('edit_theme_options'))return new WP_Error('stillform_forbidden',__('You are not allowed to install demo content.','stillform'));if(function_exists('stillform_register_content_types'))stillform_register_content_types();$spec=stillform_demo_specs();$media=[];$counts=['created'=>0,'updated'=>0,'preserved'=>0];$pages=[];foreach($spec['media']as$file=>$data){$id=stillform_demo_media($file,$data);if(is_wp_error($id))return$id;$media[$file]=$id;}foreach($spec['pages']as$slug=>$p){$r=stillform_demo_upsert('page',$slug,$p[0],$p[1],$p[2],$p[3]);if(is_wp_error($r))return$r;$counts[$r['status']]++;$pages[$slug]=$r;if($r['owned']&&$p[4])set_post_thumbnail($r['id'],$media[$p[4]]);}foreach($spec['projects']as$order=>$p){$r=stillform_demo_upsert('project',$p[0],$p[1],$p[7],$p[2]);if(is_wp_error($r))return$r;$counts[$r['status']]++;if($r['owned']){wp_update_post(['ID'=>$r['id'],'menu_order'=>$order]);update_post_meta($r['id'],'_stillform_year',$p[4]);update_post_meta($r['id'],'_stillform_status',$p[5]);wp_set_object_terms($r['id'],$p[3],'project_type');set_post_thumbnail($r['id'],$media[$p[6]]);}}foreach($spec['posts']as$p){$r=stillform_demo_upsert('post',$p[0],$p[1],$p[5],$p[2]);if(is_wp_error($r))return$r;$counts[$r['status']]++;if($r['owned']){wp_update_post(['ID'=>$r['id'],'post_date'=>$p[4],'post_date_gmt'=>get_gmt_from_date($p[4])]);set_post_thumbnail($r['id'],$media[$p[3]]);wp_set_object_terms($r['id'],'Field Notes','category');}}$home=$pages['home'];if($home['owned']||((int)get_option('page_on_front')===$home['id'])){update_option('show_on_front','page');update_option('page_on_front',$home['id']);update_option('page_for_posts',0);}$menu_id=(int)get_option('stillform_demo_menu_id');if(!$menu_id||!wp_get_nav_menu_object($menu_id)){$menu_id=wp_create_nav_menu('Stillform Demo Navigation');if(is_wp_error($menu_id))return$menu_id;update_option('stillform_demo_menu_id',(int)$menu_id);}foreach((wp_get_nav_menu_items($menu_id)?:[])as$item){if(get_post_meta($item->ID,'_stillform_demo_owner',true)===STILLFORM_DEMO_OWNER)wp_delete_post($item->ID,true);}foreach(['home','studio','projects','journal','contact']as$pos=>$slug){$page=$pages[$slug];if(!$page['owned'])continue;$item=wp_update_nav_menu_item($menu_id,0,['menu-item-title'=>get_the_title($page['id']),'menu-item-object'=>'page','menu-item-object-id'=>$page['id'],'menu-item-type'=>'post_type','menu-item-status'=>'publish','menu-item-position'=>$pos+1]);if(!is_wp_error($item))stillform_demo_mark($item,'menu-item:'.$page['id']);}$locations=get_theme_mod('nav_menu_locations',[]);$locations['primary']=$menu_id;$locations['footer']=$menu_id;set_theme_mod('nav_menu_locations',$locations);update_option('stillform_demo_install',['version'=>'1.1.0','installed_at'=>current_time('mysql'),'counts'=>$counts]);flush_rewrite_rules();return['counts'=>$counts,'media'=>count($media)];}
function stillform_admin_menu(){add_theme_page(__('Stillform demo','stillform'),__('Stillform demo','stillform'),'edit_theme_options','stillform-demo','stillform_demo_page');}add_action('admin_menu','stillform_admin_menu');
function stillform_demo_admin_post(){if(!current_user_can('edit_theme_options'))wp_die(esc_html__('You are not allowed to install demo content.','stillform'));check_admin_referer('stillform_install_demo');$r=stillform_install_demo_content();$args=is_wp_error($r)?['page'=>'stillform-demo','stillform_demo'=>'error','message'=>$r->get_error_message()]:['page'=>'stillform-demo','stillform_demo'=>'success']+$r['counts'];wp_safe_redirect(add_query_arg($args,admin_url('themes.php')));exit;}add_action('admin_post_stillform_install_demo','stillform_demo_admin_post');
function stillform_demo_page(){if(!current_user_can('edit_theme_options'))return;$status=isset($_GET['stillform_demo'])?sanitize_key(wp_unslash($_GET['stillform_demo'])):'';echo'<div class="wrap"><h1>'.esc_html__('Stillform demo content','stillform').'</h1>';if('success'===$status)printf('<div class="notice notice-success"><p>%s</p></div>',esc_html(sprintf(__('Demo install complete: %1$d created, %2$d refreshed, %3$d conflicts preserved.','stillform'),absint($_GET['created']??0),absint($_GET['updated']??0),absint($_GET['preserved']??0))));if('error'===$status)echo'<div class="notice notice-error"><p>'.esc_html(sanitize_text_field(wp_unslash($_GET['message']??''))).'</p></div>';echo'<p>'.esc_html__('This optional installer creates or refreshes theme-owned demo pages, projects, journal posts, media and navigation.','stillform').'</p><div class="notice notice-warning inline"><p><strong>'.esc_html__('Before continuing:','stillform').'</strong> '.esc_html__('It writes content, uploads bundled images, and changes the static front-page and menu-location options. Nothing runs on activation. Existing content with matching slugs is preserved and omitted from demo-owned navigation.','stillform').'</p></div><p>'.esc_html__('Running it twice is safe: only records carrying Stillform ownership metadata are refreshed.','stillform').'</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="stillform_install_demo">';wp_nonce_field('stillform_install_demo');submit_button(__('Install or refresh demo content','stillform'));echo'</form></div>';}
